package com.bank.ledgermerge;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.logging.Logger;

// Merges Priya's sorted amounts into Rajesh's pre-sized ledger in place.
public class LedgerMerger {
    private static final Logger log = Logger.getLogger(LedgerMerger.class.getName());

    // Merge second (n elems) into first (m real elems + n spare slots). O(m+n), O(1).
    public void mergeInPlace(BigDecimal[] first, int m, BigDecimal[] second, int n) {
        if (first == null || second == null) {
            throw new IllegalArgumentException("arrays must be non-null");
        }
        int i = m - 1;              // last real element of first
        int j = n - 1;              // last element of second
        int k = m + n - 1;          // last write slot in first
        while (j >= 0) {
            if (i >= 0 && first[i].compareTo(second[j]) > 0) {
                first[k--] = first[i--];   // first's tail is larger
            } else {
                first[k--] = second[j--];  // second's tail is larger (or i done)
            }
        }
        log.info(() -> "Merged ledger = " + Arrays.toString(first));
    }
}
