package com.bank.ledgermerge;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: merge Priya's amounts into Rajesh's ledger.
public class LedgerMergeDemo {
    private static final Logger log = Logger.getLogger(LedgerMergeDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    private static BigDecimal bd(String s) { return new BigDecimal(s); }

    public static void main(String[] args) {
        LedgerMerger merger = new LedgerMerger();

        // Rajesh (SAV2001) ledger: 3 real amounts + 3 spare slots (null).
        BigDecimal[] rajesh = { bd("1000"), bd("2000"), bd("3000"), null, null, null };
        // Priya (CUR3001) sorted shared amounts.
        BigDecimal[] priya = { bd("2500"), bd("2600"), bd("5000") };

        merger.mergeInPlace(rajesh, 3, priya, 3);
        log.info(() -> "Final sorted ledger ready for statement generation");
    }
}
